select id, username, display_name, phone, email, account_type, status, token_type from sys_user where
( username like concat('%',#{keyword},'%') or display_name like concat('%',#{keyword},'%') or phone like concat('%',#{keyword},'%') or email like concat('%',#{keyword},'%') )
and status=#{status}
order by id desc limit #{offset}, #{size}

select count(*) from sys_user where
( username like concat('%',#{keyword},'%') or display_name like concat('%',#{keyword},'%') or phone like concat('%',#{keyword},'%') or email like concat('%',#{keyword},'%') )
and status=#{status}
